mapper.select:
SELECT , c.CUSTOMER_NAME, w.WRITE_OFF_NO
FROM TBL_AR_BAD_DEBT_RECOVERY r
LEFT JOIN TBL_AR_CUSTOMER c ON r.CUSTOMER_ID = c.CUSTOMER_ID AND c.IS_DELETED = 0
LEFT JOIN TBL_AR_BAD_DEBT_WRITE_OFF w ON r.WRITE_OFF_ID = w.WRITE_OFF_ID AND w.IS_DELETED = 0
WHERE r.IS_DELETED = 0

    AND r.RECOVERY_NO LIKE '%' || #{param.recoveryNo} || '%'


    AND r.CUSTOMER_ID = #{param.customerId}


    AND c.CUSTOMER_NAME LIKE '%' || #{param.customerName} || '%'


    AND r.WRITE_OFF_ID = #{param.writeOffId}


    AND r.RECOVERY_DATE >= #{param.recoveryDateStart}


    AND r.RECOVERY_DATE <= #{param.recoveryDateEnd}


    AND r.TENANT_ID = #{param.tenantId}


    AND r.ORG_ID = #{param.orgId}

ORDER BY r.RECOVERY_DATE DESC

SELECT , c.CUSTOMER_NAME, w.WRITE_OFF_NO FROM TBL_AR_BAD_DEBT_RECOVERY r LEFT JOIN TBL_AR_CUSTOMER c ON r.CUSTOMER_ID = c.CUSTOMER_ID AND c.IS_DELETED = 0 LEFT JOIN TBL_AR_BAD_DEBT_WRITE_OFF w ON r.WRITE_OFF_ID = w.WRITE_OFF_ID AND w.IS_DELETED = 0 WHERE r.IS_DELETED = 0
AND r.TENANT_ID = #{param.tenantId}
ORDER BY r.RECOVERY_DATE DESC
